import sys, os, unittest
sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))
from shop.pricing import apply_tax


class TestApplyTax(unittest.TestCase):
    def test_adds_tax_and_rounds_to_cents(self):
        # 1.99 + 7% = 2.1293 -> 2.13, not a whole-unit 2
        self.assertAlmostEqual(apply_tax(1.99, 0.07), 2.13, places=2)


if __name__ == "__main__":
    unittest.main()

